// Canonical `.env` key names for exporting/importing secret-provider connection
// config (the `cli`-equivalent of secrets.json). The app exports these keys
// (Preferences → Secret Manager → Export as .env) and the CLI reads them back
// via `bru run --secrets-env-file`. Keep producer and consumer in lockstep by
// referencing these constants instead of hardcoding the strings.

export type SecretProviderType
  = | 'hashicorp-vault-server'
    | 'hashicorp-vault-cloud'
    | 'aws-secrets-manager'
    | 'azure-key-vault'
    | 'gcp-secrets-manager';

export const SECRET_PROVIDER_ENV_PREFIX: Record<SecretProviderType, string> = {
  'hashicorp-vault-server': 'BRUNO_HASHICORP_VAULT_SERVER_',
  'hashicorp-vault-cloud': 'BRUNO_HASHICORP_VAULT_CLOUD_',
  'aws-secrets-manager': 'BRUNO_AWS_SECRETS_MANAGER_',
  'azure-key-vault': 'BRUNO_AZURE_KEY_VAULT_',
  'gcp-secrets-manager': 'BRUNO_GCP_SECRETS_MANAGER_'
};

const SUFFIXES: Record<SecretProviderType, string[]> = {
  'hashicorp-vault-server': [
    'URL',
    'NAMESPACE',
    'AUTH_METHOD',
    'TOKEN',
    'APPROLE_ROLE',
    'APPROLE_ROLE_ID',
    'APPROLE_SECRET_ID',
    'APPROLE_MOUNT_PATH',
    'LDAP_USERNAME',
    'LDAP_PASSWORD'
  ],
  'hashicorp-vault-cloud': [
    'AUTH_METHOD',
    'TOKEN_ENDPOINT',
    'SECRETS_ENDPOINT',
    'CLIENT_ID',
    'CLIENT_SECRET',
    'ORGANIZATION_ID',
    'PROJECT_ID'
  ],
  'aws-secrets-manager': [
    'AUTH_METHOD',
    'PROFILE_NAME',
    'ACCESS_KEY_ID',
    'SECRET_ACCESS_KEY',
    'SESSION_TOKEN',
    'REGION'
  ],
  'azure-key-vault': ['TENANT_ID', 'CLIENT_ID', 'CLIENT_SECRET'],
  'gcp-secrets-manager': ['PROJECT_ID', 'CLIENT_EMAIL', 'PRIVATE_KEY']
};

// Full env var name per provider field, e.g.
// SECRET_PROVIDER_ENV_KEYS['hashicorp-vault-server'].URL === 'BRUNO_HASHICORP_VAULT_SERVER_URL'.
export const SECRET_PROVIDER_ENV_KEYS: Record<SecretProviderType, Record<string, string>> = Object.fromEntries(
  (Object.keys(SECRET_PROVIDER_ENV_PREFIX) as SecretProviderType[]).map((type) => [
    type,
    Object.fromEntries(SUFFIXES[type].map((suffix) => [suffix, `${SECRET_PROVIDER_ENV_PREFIX[type]}${suffix}`]))
  ])
) as Record<SecretProviderType, Record<string, string>>;
